const DB='atelier-notes-v1';
export async function openStore(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function readState(db){return new Promise((resolve,reject)=>{const t=db.transaction('workspace','readonly'),r=t.objectStore('workspace').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function writeState(db,state,expected=null){return new Promise((resolve,reject)=>{const t=db.transaction('workspace','readwrite'),store=t.objectStore('workspace');let conflict=false;if(expected===null)store.put(state,'state');else{const r=store.get('state');r.onsuccess=()=>{if((r.result?.storageRevision||0)!==expected){conflict=true;t.abort();}else store.put(state,'state');};}t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error);t.onabort=()=>reject(conflict?Error('Another tab saved newer notes. Export a backup of this tab, then reload.'):t.error||Error('Save interrupted'));});}
export function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
